void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
	vec2 q = fragCoord.xy / iResolution.xy;
    vec2 uv = q * 2.-1.;

	vec3 color = vec3(0, 1, 0);

    float power = 3.0;
    float dist = pow(abs(uv.x),power) + pow(abs(uv.y),power);

	if( dist > 1.0)
    {
    	color = vec3(1, 0, 0);
    }

    fragColor = vec4(color,1); 
}
